"use client";

import { Tooltip as TooltipPrimitive } from "@base-ui/react/tooltip";
import { mergeClassNames } from "@/lib/class-name";
import { withGlass } from "@/lib/glass/context";

function TooltipProvider({
  delay = 0,
  ...props
}: TooltipPrimitive.Provider.Props) {
  return (
    <TooltipPrimitive.Provider
      data-slot="tooltip-provider"
      delay={delay}
      {...props}
    />
  );
}

function TooltipImplementation({ ...props }: TooltipPrimitive.Root.Props) {
  return <TooltipPrimitive.Root data-slot="tooltip" {...props} />;
}

function TooltipTrigger({ ...props }: TooltipPrimitive.Trigger.Props) {
  return <TooltipPrimitive.Trigger data-slot="tooltip-trigger" {...props} />;
}

function TooltipContentImplementation({
  className,
  side = "top",
  sideOffset = 4,
  align = "center",
  alignOffset = 0,
  children,
  ...props
}: TooltipPrimitive.Popup.Props &
  Pick<
    TooltipPrimitive.Positioner.Props,
    "align" | "alignOffset" | "side" | "sideOffset"
  >) {
  return (
    <TooltipPrimitive.Portal>
      <TooltipPrimitive.Positioner
        align={align}
        alignOffset={alignOffset}
        side={side}
        sideOffset={sideOffset}
        className="isolate z-50"
      >
        <TooltipPrimitive.Popup
          data-slot="tooltip-content"
          className={mergeClassNames(
            "data-[side=bottom]:slide-in-from-top-2 data-[side=inline-end]:slide-in-from-start-2 data-[side=inline-start]:slide-in-from-end-2 data-[side=left]:slide-in-from-right-2 data-[side=right]:slide-in-from-left-2 data-[side=top]:slide-in-from-bottom-2 data-[state=delayed-open]:fade-in-0 data-[state=delayed-open]:zoom-in-95 data-open:fade-in-0 data-open:zoom-in-95 data-closed:fade-out-0 data-closed:zoom-out-95 z-50 inline-flex w-fit max-w-xs origin-(--transform-origin) items-center gap-1.5 rounded-xl bg-foreground px-3 py-1.5 text-background text-xs has-data-[slot=kbd]:pe-1.5 data-[state=delayed-open]:animate-in data-closed:animate-out data-open:animate-in **:data-[slot=kbd]:relative **:data-[slot=kbd]:isolate **:data-[slot=kbd]:z-50 **:data-[slot=kbd]:rounded-lg",
            className,
          )}
          {...props}
        >
          {children}
          <TooltipPrimitive.Arrow className="z-50 size-2.5 translate-y-[calc(-50%-2px)] rotate-45 rounded-[2px] bg-foreground fill-foreground data-[side=inline-end]:-start-1 data-[side=inline-start]:-end-1 data-[side=bottom]:top-1 data-[side=inline-end]:top-1/2! data-[side=inline-start]:top-1/2! data-[side=left]:top-1/2! data-[side=right]:top-1/2! data-[side=left]:-right-1 data-[side=top]:-bottom-2.5 data-[side=right]:-left-1 data-[side=inline-end]:translate-x-[1.5px] data-[side=inline-start]:translate-x-[-1.5px] data-[side=left]:translate-x-[-1.5px] data-[side=right]:translate-x-[1.5px] data-[side=inline-end]:-translate-y-1/2 data-[side=inline-start]:-translate-y-1/2 data-[side=left]:-translate-y-1/2 data-[side=right]:-translate-y-1/2 rtl:data-[side=inline-end]:-translate-x-[1.5px] rtl:data-[side=inline-start]:-translate-x-[-1.5px] rtl:data-[side=left]:-translate-x-[-1.5px] rtl:data-[side=right]:-translate-x-[1.5px]" />
        </TooltipPrimitive.Popup>
      </TooltipPrimitive.Positioner>
    </TooltipPrimitive.Portal>
  );
}

const Tooltip = withGlass(TooltipImplementation, "scope");

const TooltipContent = withGlass(TooltipContentImplementation, "portal");

export { Tooltip, TooltipContent, TooltipProvider, TooltipTrigger };

import { cn } from "cn";

/** Preserve Base UI state callbacks while merging the component's classes. */
export function mergeClassNames<State>(
  base: string,
  className: string | ((state: State) => string | undefined) | undefined,
) {
  if (typeof className === "function")
    return (state: State) => cn(base, className(state));
  return cn(base, className);
}

import type { GlassMaterial, GlassMode } from "@/lib/glass/context";
import type { GlassRenderer } from "@/lib/glass/renderer";
import type { SvgGlassRenderer } from "@/lib/glass/svg-renderer";

type Backend =
  | { kind: "vgpu"; renderer: GlassRenderer }
  | { kind: "svg"; renderer: SvgGlassRenderer };
let gpu: Promise<Backend | undefined> | undefined;
let svg: Promise<Backend | undefined> | undefined;
let gpuInstance: GlassRenderer | undefined;
let svgInstance: SvgGlassRenderer | undefined;
let controller = new AbortController();
let gpuFailed = false;
let svgFailed = false;

export function glassBaseOnly(mode: GlassMode = "svg") {
  return (
    mode === "css" ||
    window.matchMedia?.(
      "(prefers-reduced-transparency: reduce), (forced-colors: active)",
    ).matches
  );
}

export async function prepareGlassRenderer(
  mode: GlassMode = "svg",
  material: GlassMaterial = "clear",
) {
  if (glassBaseOnly(mode)) return;
  const session = controller;
  if (mode === "auto" && material === "clear" && !gpuFailed) {
    gpu ??= (async () => {
      try {
        const { GlassRenderer } = await import("@/lib/glass/renderer");
        const renderer = await GlassRenderer.create(session.signal);
        if (session.signal.aborted) {
          renderer.destroy();
          return;
        }
        gpuInstance = renderer;
        return { kind: "vgpu", renderer } satisfies Backend;
      } catch {
        if (!session.signal.aborted) gpuFailed = true;
      }
    })();
    const backend = await gpu;
    if (session.signal.aborted) return;
    if (backend && !gpuFailed) return backend;
  }
  if (svgFailed) return;
  svg ??= (async () => {
    try {
      const { SvgGlassRenderer } = await import("@/lib/glass/svg-renderer");
      const renderer = await SvgGlassRenderer.create();
      if (session.signal.aborted) {
        renderer.destroy();
        return;
      }
      svgInstance = renderer;
      return { kind: "svg", renderer } satisfies Backend;
    } catch {
      if (!session.signal.aborted) svgFailed = true;
    }
  })();
  const backend = await svg;
  if (!session.signal.aborted && !svgFailed) return backend;
}

export function failGlassRenderer(kind: Backend["kind"]) {
  if (kind === "vgpu") {
    gpuFailed = true;
    gpuInstance?.destroy();
    gpuInstance = undefined;
  } else {
    svgFailed = true;
    svgInstance?.destroy();
    svgInstance = undefined;
  }
}

export function releaseGlassRenderers() {
  controller.abort();
  gpuInstance?.destroy();
  svgInstance?.destroy();
  gpuInstance = undefined;
  svgInstance = undefined;
  gpu = undefined;
  svg = undefined;
  gpuFailed = false;
  svgFailed = false;
  controller = new AbortController();
}

import { glassSamplePadding } from "@/lib/glass/refraction";

export type GlassCaptureBounds = Pick<
  DOMRect,
  "left" | "top" | "right" | "bottom"
>;

export function glassCaptureRatio() {
  return Math.min(2, Math.sqrt(8_388_608 / (innerWidth * innerHeight)));
}

// Align shared requests to the existing half-resolution Gaussian pixel grid.
export function glassMediaBounds(
  requests: readonly (GlassCaptureBounds & { width: number; height: number })[],
): GlassCaptureBounds | undefined {
  let left = Infinity;
  let top = Infinity;
  let right = -Infinity;
  let bottom = -Infinity;
  for (const rect of requests) {
    if (
      !rect.width ||
      !rect.height ||
      rect.right <= 0 ||
      rect.bottom <= 0 ||
      rect.left >= innerWidth ||
      rect.top >= innerHeight
    )
      continue;
    left = Math.min(left, rect.left - glassSamplePadding);
    top = Math.min(top, rect.top - glassSamplePadding);
    right = Math.max(right, rect.right + glassSamplePadding);
    bottom = Math.max(bottom, rect.bottom + glassSamplePadding);
  }
  if (!Number.isFinite(left)) return;
  const ratio = glassCaptureRatio();
  const axis = (start: number, end: number, size: number) => {
    const pixels = Math.floor(size * ratio);
    // Odd full dimensions change the downsampling grid; retain that axis.
    if (pixels % 2) return [0, pixels / ratio];
    return [
      Math.max(0, Math.floor((start * ratio) / 2) * 2) / ratio,
      Math.min(pixels, Math.ceil((end * ratio) / 2) * 2) / ratio,
    ];
  };
  const [x0, x1] = axis(left, right, innerWidth);
  const [y0, y1] = axis(top, bottom, innerHeight);
  return { left: x0, top: y0, right: x1, bottom: y1 };
}

export function glassMediaSource(target: HTMLElement) {
  if (target.dataset.glassCapture !== "media") return undefined;
  const media = target.querySelector<HTMLVideoElement | HTMLImageElement>(
    "[data-glass-backdrop]",
  );
  if (!media || media.closest("[data-glass-exclude]")) return undefined;
  return media;
}

// A dedicated media-only capture target avoids serializing UI for each video frame.
export async function captureGlassMedia(
  target: HTMLElement,
  region?: GlassCaptureBounds,
) {
  const media = glassMediaSource(target);
  if (!media) return undefined;
  let source = media;
  if (media.tagName === "VIDEO") {
    const video = media as HTMLVideoElement;
    if (
      video.poster &&
      video.paused &&
      video.currentTime === 0 &&
      video.played.length === 0
    ) {
      const poster = target.ownerDocument.createElement("img");
      if (video.crossOrigin) poster.crossOrigin = video.crossOrigin;
      poster.src = video.poster;
      await poster.decode();
      source = poster;
    }
  }
  let width: number;
  let height: number;
  if (source.tagName === "VIDEO") {
    const video = source as HTMLVideoElement;
    if (video.readyState < 2) throw new Error("Glass video is not ready");
    width = video.videoWidth;
    height = video.videoHeight;
  } else {
    const image = source as HTMLImageElement;
    width = image.naturalWidth;
    height = image.naturalHeight;
  }
  if (!width || !height) throw new Error("Glass media is not ready");
  const bounds = media.getBoundingClientRect();
  const clip = target.getBoundingClientRect();
  const style = getComputedStyle(media);
  if (style.objectFit !== "cover" && style.objectFit !== "contain")
    throw new Error("Glass media capture requires cover or contain");
  const canvas = target.ownerDocument.createElement("canvas");
  const ratio = glassCaptureRatio();
  const origin: [number, number] = [region?.left ?? 0, region?.top ?? 0];
  canvas.width = Math.max(
    1,
    region
      ? Math.round((region.right - region.left) * ratio)
      : Math.floor(innerWidth * ratio),
  );
  canvas.height = Math.max(
    1,
    region
      ? Math.round((region.bottom - region.top) * ratio)
      : Math.floor(innerHeight * ratio),
  );
  const context = canvas.getContext("2d", { willReadFrequently: true });
  if (!context) throw new Error("Glass media canvas unavailable");
  const scale =
    style.objectFit === "cover"
      ? Math.max(bounds.width / width, bounds.height / height)
      : Math.min(bounds.width / width, bounds.height / height);
  const paintedWidth = width * scale;
  const paintedHeight = height * scale;
  context.save();
  context.scale(ratio, ratio);
  if (region) context.translate(-origin[0], -origin[1]);
  context.beginPath();
  context.rect(clip.left, clip.top, clip.width, clip.height);
  context.clip();
  context.drawImage(
    source,
    bounds.left + (bounds.width - paintedWidth) / 2,
    bounds.top + (bounds.height - paintedHeight) / 2,
    paintedWidth,
    paintedHeight,
  );
  context.restore();
  context.getImageData(0, 0, 1, 1);
  return { canvas, ratio, origin };
}

import {
  captureGlassMedia,
  type GlassCaptureBounds,
  glassCaptureRatio,
} from "@/lib/glass/capture-media";

type CaptureOptions = NonNullable<
  Parameters<typeof import("html-to-image").toSvg>[1]
>;

export class GlassResourceError extends Error {}

let library:
  | Promise<{
      getFontEmbedCSS: typeof import("html-to-image").getFontEmbedCSS;
      cloneNode: typeof import("html-to-image/es/clone-node").cloneNode;
      embedImages: typeof import("html-to-image/es/embed-images").embedImages;
    }>
  | undefined;
type FontVersion = {
  value: number;
  leases: number;
  changed: () => void;
  cache: WeakMap<HTMLElement, { key: string; css: Promise<string> }>;
};
const fontVersions = new WeakMap<Document, FontVersion>();
const marker = "data-glass-capture-id";
let sequence = 0;
let capturing = false;
const unfinishedSamples = new Set<Promise<unknown>>();
const retiredFrames = new Set<string>();
const captureGeometry = new WeakMap<
  HTMLCanvasElement,
  { ratio: number; origin: readonly [number, number] }
>();

function releaseRetiredFrames() {
  if (capturing || unfinishedSamples.size) return;
  for (const url of retiredFrames) URL.revokeObjectURL(url);
  retiredFrames.clear();
}

// DOM embedding can still be reading a frame after its surface changes mode.
export function releaseGlassFrame(url: string) {
  retiredFrames.add(url);
  releaseRetiredFrames();
}

export function glassCapturePixelRatio(source: HTMLCanvasElement) {
  return captureGeometry.get(source)?.ratio ?? 1;
}

export function glassCaptureOrigin(
  source: HTMLCanvasElement,
): readonly [number, number] {
  return captureGeometry.get(source)?.origin ?? [0, 0];
}

function loadLibrary() {
  library ??= Promise.all([
    import("html-to-image"),
    import("html-to-image/es/clone-node"),
    import("html-to-image/es/embed-images"),
  ])
    .then(([fonts, clone, images]) => ({
      getFontEmbedCSS: fonts.getFontEmbedCSS,
      cloneNode: clone.cloneNode,
      embedImages: images.embedImages,
    }))
    .catch((error) => {
      library = undefined;
      throw error;
    });
  return library;
}

function bounded<T>(operation: Promise<T>, milliseconds: number) {
  return new Promise<T>((resolve, reject) => {
    const timer = setTimeout(
      () => reject(new Error("Glass background capture timed out")),
      milliseconds,
    );
    operation.then(
      (result) => {
        clearTimeout(timer);
        resolve(result);
      },
      (error) => {
        clearTimeout(timer);
        reject(error);
      },
    );
  });
}

function sample<T>(operation: Promise<T>, milliseconds: number) {
  // html-to-image has no cancellation API. A deadline returns to the CSS
  // fallback, but the real font/DOM task keeps the sampling lease until it ends.
  unfinishedSamples.add(operation);
  const release = () => {
    unfinishedSamples.delete(operation);
    releaseRetiredFrames();
  };
  void operation.then(release, release);
  return bounded(operation, milliseconds);
}

function included(
  element: Element,
  blocked: Set<Element>,
  keepPlaceholder = false,
) {
  return (
    !element.closest(
      "script,iframe,video,[data-glass-exclude],[data-glass-decoration]",
    ) &&
    !Array.from(blocked).some(
      (item) =>
        (item === element && !keepPlaceholder) ||
        (item !== element && item.contains(element)),
    )
  );
}

type Placement = {
  element: HTMLElement;
  id: string;
  previous: string | null;
  rect: DOMRect;
  scrollLeft: number;
  scrollTop: number;
  pinned: boolean;
  hidden: boolean;
};

export function glassLayoutSize(
  element: HTMLElement,
  rect = element.getBoundingClientRect(),
) {
  const style = getComputedStyle(element);
  const dimension = (axis: "width" | "height") => {
    const value = Number.parseFloat(style[axis]);
    if (Number.isFinite(value) && value > 0) {
      if (style.boxSizing === "border-box") return value;
      const sides = axis === "width" ? ["Left", "Right"] : ["Top", "Bottom"];
      return (
        value +
        sides.reduce(
          (sum, side) =>
            sum +
            (Number.parseFloat(
              style.getPropertyValue(`padding-${side.toLowerCase()}`),
            ) || 0) +
            (Number.parseFloat(
              style.getPropertyValue(`border-${side.toLowerCase()}-width`),
            ) || 0),
          0,
        )
      );
    }
    return (
      (axis === "width" ? element.offsetWidth : element.offsetHeight) ||
      rect[axis]
    );
  };
  return { width: dimension("width"), height: dimension("height") };
}

function axisAligned(element: HTMLElement) {
  for (
    let current: HTMLElement | null = element;
    current;
    current = current.parentElement
  ) {
    const style = getComputedStyle(current);
    if (style.perspective && style.perspective !== "none") return false;
    if (
      style.rotate &&
      style.rotate !== "none" &&
      !/^0(?:deg|rad|turn)?$/.test(style.rotate)
    )
      return false;
    if (style.scale && style.scale !== "none") {
      const scale = style.scale.split(/\s+/).map(Number);
      if (scale.some((value) => !Number.isFinite(value) || value <= 0))
        return false;
    }
    const transform = style.transform;
    if (!transform || transform === "none") continue;
    const matrix = transform.match(/^matrix\(([^)]+)\)$/);
    if (matrix) {
      const values = matrix[1].split(",").map(Number);
      const [a, b, c, d, x, y] = values;
      if (
        values.length === 6 &&
        a > 0 &&
        d > 0 &&
        b === 0 &&
        c === 0 &&
        Number.isFinite(x) &&
        Number.isFinite(y)
      )
        continue;
    }
    const matrix3d = transform.match(/^matrix3d\(([^)]+)\)$/);
    if (matrix3d) {
      const values = matrix3d[1].split(",").map(Number);
      if (
        values.length === 16 &&
        values.every(Number.isFinite) &&
        values[0] > 0 &&
        values[5] > 0 &&
        values[10] === 1 &&
        values[15] === 1 &&
        [1, 2, 3, 4, 6, 7, 8, 9, 11, 14].every((index) => values[index] === 0)
      )
        continue;
    }
    return false;
  }
  return true;
}

function prepare(
  target: HTMLElement,
  blocked: Set<Element>,
  placements: Placement[],
) {
  const canvasParents = new Set(
    [...blocked]
      .filter((element) => element.localName === "canvas")
      .map((element) => element.parentElement),
  );
  for (const element of [
    target,
    ...target.querySelectorAll<HTMLElement>("*"),
  ]) {
    if (!included(element, blocked, true)) continue;
    const position = getComputedStyle(element).position;
    const hidden = blocked.has(element);
    const pinned =
      element !== target && (position === "fixed" || position === "sticky");
    if (
      !hidden &&
      !pinned &&
      !element.scrollTop &&
      !element.scrollLeft &&
      !canvasParents.has(element)
    )
      continue;
    const id = String(++sequence);
    placements.push({
      element,
      id,
      previous: element.getAttribute(marker),
      rect: element.getBoundingClientRect(),
      scrollLeft: element.scrollLeft,
      scrollTop: element.scrollTop,
      pinned,
      hidden,
    });
    element.setAttribute(marker, id);
  }
  return placements;
}

function restore(placements: Placement[]) {
  for (const { element, previous } of placements) {
    if (previous === null) element.removeAttribute(marker);
    else element.setAttribute(marker, previous);
  }
}

function layoutPlaceholder(element: HTMLElement, style: CSSStyleDeclaration) {
  const placeholder = element.ownerDocument.createElementNS(
    "http://www.w3.org/1999/xhtml",
    "div",
  );
  placeholder.id = element.id;
  for (const property of Array.from(style))
    placeholder.style.setProperty(
      property,
      style.getPropertyValue(property),
      style.getPropertyPriority(property),
    );
  if (placeholder.style.display === "inline")
    placeholder.style.display = "inline-block";
  return placeholder;
}

function repairClone(
  root: Element,
  placements: Placement[],
  target: HTMLElement,
  blocked: Set<Element>,
) {
  const clones = new Map<HTMLElement, HTMLElement>();
  for (const item of placements) {
    const clone = root.matches(`[${marker}="${item.id}"]`)
      ? root
      : root.querySelector(`[${marker}="${item.id}"]`);
    if (clone) clones.set(item.element, clone as HTMLElement);
  }
  for (const item of placements) {
    let clone = clones.get(item.element);
    // The library must not serialize excluded canvas pixels, even when tainted.
    if (!clone && item.hidden && item.element.localName === "canvas") {
      const originalParent = item.element.parentElement;
      const parent = originalParent && clones.get(originalParent);
      if (
        !originalParent ||
        !parent ||
        originalParent.localName === "slot" ||
        originalParent.shadowRoot ||
        item.element.assignedSlot
      )
        throw new GlassResourceError(
          "Glass canvas placeholder has unsupported layout",
        );
      const index = [...originalParent.childNodes]
        .filter(
          (node) => !(node instanceof Element) || included(node, blocked, true),
        )
        .indexOf(item.element);
      clone = layoutPlaceholder(item.element, getComputedStyle(item.element));
      parent.insertBefore(clone, parent.childNodes[index] ?? null);
      clones.set(item.element, clone);
    }
    if (!clone) continue;
    if (item.hidden) {
      if (clone.matches("img,image,canvas,svg,iframe")) {
        const placeholder = layoutPlaceholder(clone, clone.style);
        clone.replaceWith(placeholder);
        clone = placeholder;
        clones.set(item.element, clone);
      }
      const size = glassLayoutSize(item.element, item.rect);
      clone.style.width = `${size.width}px`;
      clone.style.height = `${size.height}px`;
      clone.style.boxSizing = "border-box";
      clone.style.visibility = "hidden";
      clone.style.backgroundImage = "none";
      clone.style.maskImage = "none";
      for (const attribute of ["src", "srcset", "href", "xlink:href"])
        clone.removeAttribute(attribute);
      clone.replaceChildren();
      continue;
    }
    if (!item.pinned) continue;
    let parent = item.element.parentElement;
    while (parent && parent !== target) {
      const style = getComputedStyle(parent);
      if (
        style.position !== "static" ||
        style.transform !== "none" ||
        parent.scrollTop ||
        parent.scrollLeft
      )
        break;
      parent = parent.parentElement;
    }
    parent ??= target;
    const bounds = parent.getBoundingClientRect();
    if (!axisAligned(parent) || !axisAligned(item.element))
      throw new Error("Glass pinned content has unsupported geometry");
    const parentSize = glassLayoutSize(parent, bounds);
    const scaleX = bounds.width / parentSize.width;
    const scaleY = bounds.height / parentSize.height;
    const width = item.rect.width / scaleX;
    const height = item.rect.height / scaleY;
    const itemSize = glassLayoutSize(item.element, item.rect);
    const localScaleX = width / itemSize.width;
    const localScaleY = height / itemSize.height;
    const scrollContainer = Boolean(parent.scrollTop || parent.scrollLeft);
    const padding = getComputedStyle(parent);
    const paddingTop = scrollContainer
      ? Number.parseFloat(padding.paddingTop) || 0
      : 0;
    const paddingLeft = scrollContainer
      ? Number.parseFloat(padding.paddingLeft) || 0
      : 0;
    if (getComputedStyle(item.element).position === "sticky") {
      const placeholder = clone.ownerDocument.createElementNS(
        "http://www.w3.org/1999/xhtml",
        "div",
      );
      placeholder.style.cssText = `width:${itemSize.width}px;height:${itemSize.height}px;flex-shrink:0;visibility:hidden`;
      clone.before(placeholder);
    }
    Object.assign(clone.style, {
      position: "absolute",
      top: `${(item.rect.top - bounds.top) / scaleY - parent.clientTop - paddingTop + parent.scrollTop}px`,
      left: `${(item.rect.left - bounds.left) / scaleX - parent.clientLeft - paddingLeft + parent.scrollLeft}px`,
      right: "auto",
      bottom: "auto",
      width: `${itemSize.width}px`,
      height: `${itemSize.height}px`,
      boxSizing: "border-box",
      margin: "0",
      transform:
        localScaleX === 1 && localScaleY === 1
          ? "none"
          : `scale(${localScaleX},${localScaleY})`,
      transformOrigin: "0 0",
      translate: "none",
      rotate: "none",
      scale: "none",
      zoom: "1",
    });
  }
  // Scroll offsets are not serialized by foreignObject. Move only the clone's
  // contents, retaining the original scroll container's clipping and background.
  for (const item of placements) {
    const clone = clones.get(item.element);
    if (!clone || item.hidden || (!item.scrollLeft && !item.scrollTop))
      continue;
    if (clone.matches("input,textarea,select")) {
      if (item.scrollLeft || item.scrollTop)
        throw new Error(
          "Scrolled native form content cannot be captured faithfully",
        );
      continue;
    }
    // Keep XHTML children so the eventual foreignObject retains HTML layout.
    const contents = clone.ownerDocument.createElementNS(
      "http://www.w3.org/1999/xhtml",
      "div",
    );
    const style = getComputedStyle(item.element);
    const paddingX =
      (Number.parseFloat(style.paddingLeft) || 0) +
      (Number.parseFloat(style.paddingRight) || 0);
    const paddingY =
      (Number.parseFloat(style.paddingTop) || 0) +
      (Number.parseFloat(style.paddingBottom) || 0);
    const width = item.element.clientWidth || item.rect.width;
    const height = item.element.clientHeight || item.rect.height;
    contents.style.cssText = `position:relative;width:${Math.max(0, width - paddingX)}px;height:${Math.max(0, height - paddingY)}px;transform:translate(${-item.scrollLeft}px,${-item.scrollTop}px);transform-origin:0 0`;
    for (const property of [
      "display",
      "flex-direction",
      "flex-wrap",
      "justify-content",
      "align-items",
      "align-content",
      "gap",
      "row-gap",
      "column-gap",
      "grid-template-columns",
      "grid-template-rows",
      "grid-auto-columns",
      "grid-auto-rows",
      "grid-auto-flow",
    ])
      contents.style.setProperty(property, style.getPropertyValue(property));
    clone.style.display = "block";
    contents.append(...clone.childNodes);
    clone.append(contents);
  }
  for (const clone of [root, ...root.querySelectorAll(`[${marker}]`)])
    clone.removeAttribute(marker);
  // Resolved background-image is retained; its original frame variable is redundant.
  for (const clone of [
    root,
    ...root.querySelectorAll<HTMLElement>("[style]"),
  ]) {
    const style = (clone as HTMLElement).style;
    if (!style) continue;
    for (const property of Array.from(style)) {
      if (property.startsWith("--glass-")) style.removeProperty(property);
    }
  }
}

function fontVersion(document: Document) {
  let version = fontVersions.get(document);
  if (!version) {
    version = { value: 0, leases: 0, changed: () => {}, cache: new WeakMap() };
    const current = version;
    version.changed = () => current.value++;
    fontVersions.set(document, version);
  }
  return version;
}

export function acquireGlassCaptureFonts(document: Document) {
  const version = fontVersion(document);
  if (version.leases++ === 0) {
    // Fonts may have changed while no scope was sampling this document.
    version.value++;
    document.fonts?.addEventListener("loadingdone", version.changed);
    document.fonts?.addEventListener("loadingerror", version.changed);
  }
  let released = false;
  return () => {
    if (released) return;
    released = true;
    if (--version.leases > 0) return;
    document.fonts?.removeEventListener("loadingdone", version.changed);
    document.fonts?.removeEventListener("loadingerror", version.changed);
    version.cache = new WeakMap();
  };
}

function fontKey(target: HTMLElement) {
  const version = fontVersion(target.ownerDocument);
  const families = new Set<string>();
  for (const node of [target, ...target.querySelectorAll("*")])
    families.add(getComputedStyle(node).fontFamily);
  const sheets = Array.from(target.ownerDocument.styleSheets, (sheet) => {
    try {
      return `${sheet.href ?? ""}:${Array.from(sheet.cssRules, (rule) => rule.cssText).join("")}`;
    } catch {
      return sheet.href ?? "";
    }
  });
  return `${sheets.join("|")}|${Array.from(families).sort().join("|")}|${target.ownerDocument.fonts?.status}|${version.value}`;
}

async function embeddedFonts(target: HTMLElement) {
  const key = fontKey(target);
  const fontCache = fontVersion(target.ownerDocument).cache;
  let cached = fontCache.get(target);
  if (cached?.key !== key) {
    const { getFontEmbedCSS } = await loadLibrary();
    const css = sample(
      getFontEmbedCSS(target, { preferredFontFormat: "woff2" }),
      4000,
    );
    cached = { key, css };
    fontCache.set(target, cached);
    css.catch(() => {
      if (fontCache.get(target)?.css === css) fontCache.delete(target);
    });
  }
  return cached.css;
}

async function imageReadiness(target: HTMLElement, blocked: Set<Element>) {
  const images = [
    ...(target.matches("img") ? [target as HTMLImageElement] : []),
    ...target.querySelectorAll<HTMLImageElement>("img"),
  ];
  await Promise.all(
    images.map(async (image) => {
      if (!included(image, blocked) || !image.getAttribute("src")) return;
      if (!image.complete) await bounded(image.decode(), 3000);
      if (!image.naturalWidth)
        throw new GlassResourceError(
          "Glass background contains a failed image",
        );
    }),
  );
}

function validateResources(root: Element) {
  for (const image of root.querySelectorAll("img,image")) {
    const source =
      image.getAttribute("src") ??
      image.getAttribute("href") ??
      image.getAttribute("xlink:href");
    if (source && !source.startsWith("data:"))
      throw new GlassResourceError(
        "Glass background contains an unreadable image",
      );
    if (source === "")
      throw new GlassResourceError("Glass background image embedding failed");
  }
  const source = [root, ...root.querySelectorAll("*")]
    .map(
      (element) =>
        `${element.getAttribute("style") ?? ""}${element.localName === "style" ? element.textContent : ""}`,
    )
    .join("\n");
  for (const match of source.matchAll(
    /url\(\s*(?:"((?:\\.|[^"\\])*)"|'((?:\\.|[^'\\])*)'|([^)'"\s]*))\s*\)/g,
  )) {
    const resource = match[1] ?? match[2] ?? match[3] ?? "";
    if (
      !resource ||
      (!resource.startsWith("data:") && !resource.startsWith("#"))
    )
      throw new GlassResourceError(
        "Glass background resource embedding failed",
      );
  }
}

async function captureBackground(
  target: HTMLElement,
  blocked: Set<Element>,
  mediaOnly: boolean,
  region?: GlassCaptureBounds,
): Promise<HTMLCanvasElement> {
  if (!target.isConnected || !included(target, blocked))
    throw new Error("Glass capture target unavailable");
  const bounds = target.getBoundingClientRect();
  if (!bounds.width || !bounds.height || !axisAligned(target))
    throw new Error("Glass capture target has unsupported geometry");
  const media = await bounded(
    captureGlassMedia(target, mediaOnly ? region : undefined),
    5000,
  );
  if (media && mediaOnly) {
    captureGeometry.set(media.canvas, {
      ratio: media.ratio,
      origin: media.origin,
    });
    return media.canvas;
  }
  const size = glassLayoutSize(target, bounds);
  const scaleX = bounds.width / size.width;
  const scaleY = bounds.height / size.height;
  await bounded(target.ownerDocument.fonts?.ready ?? Promise.resolve(), 1500);
  await imageReadiness(target, blocked);
  const { cloneNode, embedImages } = await loadLibrary();
  const fontEmbedCSS = await embeddedFonts(target);
  const placements: Placement[] = [];
  let content: HTMLElement;
  try {
    prepare(target, blocked, placements);
    const options: CaptureOptions = {
      // Computed paint resolves variables; copying inherited SVG data into every clone is redundant.
      includeStyleProperties: Array.from(
        getComputedStyle(target.ownerDocument.documentElement),
      ).filter((property) => !property.startsWith("--")),
      width: size.width,
      height: size.height,
      fontEmbedCSS,
      pixelRatio: 1,
      style: {
        position: "relative",
        left: "0",
        top: "0",
        margin: "0",
        width: `${size.width}px`,
        height: `${size.height}px`,
        boxSizing: "border-box",
        maxWidth: "none",
        maxHeight: "none",
        animation: "none",
        transition: "none",
        transform: "none",
        translate: "none",
        scale: "none",
        rotate: "none",
        zoom: "1",
      },
      filter: (node) =>
        !(node instanceof Element) ||
        (included(node, blocked, true) &&
          !(node.localName === "canvas" && blocked.has(node))),
      onImageErrorHandler: () => {
        throw new GlassResourceError("Glass background image embedding failed");
      },
    };
    content = await sample(
      (async () => {
        const clone = await cloneNode(target, options, true).catch((error) => {
          if (error instanceof Error && error.name === "SecurityError")
            throw new GlassResourceError(
              "Glass background canvas is unreadable",
              {
                cause: error,
              },
            );
          throw error;
        });
        if (!clone) throw new Error("Glass capture content missing");
        // Strip excluded resources before embedding, while retaining their layout.
        repairClone(clone, placements, target, blocked);
        Object.assign(clone.style, options.style);
        if (fontEmbedCSS) {
          const fonts = target.ownerDocument.createElement("style");
          fonts.textContent = fontEmbedCSS;
          clone.prepend(fonts);
        }
        await embedImages(clone, options);
        return clone;
      })(),
      6000,
    );
  } finally {
    restore(placements);
  }
  const root = document.createElementNS("http://www.w3.org/2000/svg", "svg");
  const foreign = document.createElementNS(
    "http://www.w3.org/2000/svg",
    "foreignObject",
  );
  foreign.append(content);
  root.append(foreign);
  validateResources(root);
  const ratio = glassCaptureRatio();
  const pixelWidth = Math.max(1, Math.floor(innerWidth * ratio));
  const pixelHeight = Math.max(1, Math.floor(innerHeight * ratio));
  root.setAttribute("width", String(innerWidth));
  root.setAttribute("height", String(innerHeight));
  root.setAttribute("viewBox", `0 0 ${innerWidth} ${innerHeight}`);
  foreign.setAttribute(
    "x",
    scaleX === 1 && scaleY === 1 ? String(bounds.left) : "0",
  );
  foreign.setAttribute(
    "y",
    scaleX === 1 && scaleY === 1 ? String(bounds.top) : "0",
  );
  foreign.setAttribute("width", String(size.width));
  foreign.setAttribute("height", String(size.height));
  if (scaleX !== 1 || scaleY !== 1)
    foreign.setAttribute(
      "transform",
      `matrix(${scaleX} 0 0 ${scaleY} ${bounds.left} ${bounds.top})`,
    );
  const image = new Image();
  const ready = new Promise<void>((resolve, reject) => {
    image.onload = () => resolve();
    image.onerror = () =>
      reject(new Error("Glass background SVG rasterization failed"));
  });
  image.src = `data:image/svg+xml;charset=utf-8,${encodeURIComponent(new XMLSerializer().serializeToString(root))}`;
  try {
    await bounded(ready, 3000);
  } finally {
    image.onload = image.onerror = null;
  }
  const canvas = document.createElement("canvas");
  canvas.width = pixelWidth;
  canvas.height = pixelHeight;
  captureGeometry.set(canvas, { ratio, origin: [0, 0] });
  const context = canvas.getContext("2d");
  if (!context) throw new Error("Glass background canvas unavailable");
  if (media) context.drawImage(media.canvas, 0, 0);
  context.drawImage(image, 0, 0, pixelWidth, pixelHeight);
  context.getImageData(0, 0, 1, 1);
  return canvas;
}

export async function captureGlassBackground(
  target: HTMLElement,
  blocked: Set<Element>,
  mediaOnly = true,
  region?: GlassCaptureBounds,
): Promise<HTMLCanvasElement> {
  if (capturing || unfinishedSamples.size)
    throw new Error("Glass background capture still active");
  capturing = true;
  try {
    return await captureBackground(target, new Set(blocked), mediaOnly, region);
  } finally {
    capturing = false;
    releaseRetiredFrames();
  }
}

"use client";

import {
  type ComponentType,
  type CSSProperties,
  createContext,
  type RefObject,
  useContext,
  useEffectEvent,
  useId,
  useLayoutEffect,
  useMemo,
  useState,
} from "react";
import type { GlassMaterial } from "@/lib/glass/defaults";
import { acquireGlass, updateGlassConfiguration } from "@/lib/glass/runtime";

export type { GlassMaterial } from "@/lib/glass/defaults";

export type GlassMode = "css" | "svg" | "auto";

export type GlassOptions = {
  strength?: number;
  tint?: string;
  tintOpacity?: number;
  highlight?: number;
};

export type GlassCaptureTarget =
  | HTMLElement
  | null
  | RefObject<HTMLElement | null>;

export type GlassConfig = {
  mode?: GlassMode;
  material?: GlassMaterial;
  options?: GlassOptions;
  captureTarget?: GlassCaptureTarget;
};

export type GlassConfiguration = GlassConfig & { id: string };

type GlassContextValue = {
  configuration?: GlassConfig;
  enabled: boolean;
  surface: boolean;
};

export const GlassContext = createContext<GlassContextValue>({
  enabled: false,
  surface: false,
});

export type GlassProps = { glass?: boolean; glassConfig?: GlassConfig };

export function withGlass<P extends object>(
  Component: ComponentType<P>,
  kind: "surface" | "control" | "scope" | "portal" = "surface",
  overrides?: Pick<GlassConfig, "mode" | "material">,
) {
  function GlassComponent({ glass, glassConfig, ...props }: P & GlassProps) {
    const context = useContext(GlassContext);
    const id = useId();
    const [mounted, setMounted] = useState(false);
    const enabled =
      glass ??
      (context.enabled &&
        (kind === "scope" || kind === "portal" || !context.surface));
    const configuration = useMemo(() => {
      return {
        ...context.configuration,
        ...glassConfig,
        ...overrides,
        options: {
          ...context.configuration?.options,
          ...glassConfig?.options,
        },
      };
    }, [context.configuration, glassConfig]);
    const initialConfiguration = useEffectEvent(() => configuration);
    const mode = configuration?.mode;
    const surface = enabled && kind !== "scope";
    useLayoutEffect(() => {
      if (!surface) return;
      setMounted(true);
      return acquireGlass({ ...initialConfiguration(), id, mode });
    }, [surface, id, mode]);
    useLayoutEffect(() => {
      if (surface && configuration)
        updateGlassConfiguration({ ...configuration, id, mode });
    }, [surface, configuration, id, mode]);
    const part =
      glass === undefined &&
      context.enabled &&
      context.surface &&
      (kind === "surface" || kind === "control");
    let childSurface = context.surface || surface;
    if (kind === "scope") childSurface = glass !== true && context.surface;
    const options = configuration?.options;
    const originalStyle = (
      props as {
        style?: CSSProperties | ((state: unknown) => CSSProperties | undefined);
      }
    ).style;
    const materialStyle = {} as CSSProperties & Record<string, unknown>;
    if (options?.tint) materialStyle["--glass-base"] = options.tint;
    if (Number.isFinite(options?.tintOpacity))
      materialStyle["--glass-opacity"] =
        `${Math.min(1, Math.max(0, options?.tintOpacity ?? 0)) * 100}%`;
    if (options?.highlight === 0) {
      materialStyle["--glass-edge"] = "none";
      materialStyle["--glass-initial-edge-shadow"] = "0 0 #0000";
    }
    let initialStyle = originalStyle;
    if (Object.keys(materialStyle).length) {
      if (typeof originalStyle === "function")
        initialStyle = (state: unknown) => ({
          ...originalStyle(state),
          ...materialStyle,
        });
      else initialStyle = { ...originalStyle, ...materialStyle };
    }
    return (
      <GlassContext.Provider
        value={{
          configuration,
          enabled: enabled || (glass === undefined && context.enabled),
          surface: childSurface,
        }}
      >
        <Component
          {...(props as P)}
          {...(part ? { "data-glass-part": kind } : {})}
          {...(surface
            ? {
                style: initialStyle,
                "data-glass": "true",
                "data-glass-scope": id,
                "data-glass-material": configuration?.material ?? "clear",
                "data-glass-state": "loading",
                "data-glass-mounted": mounted,
              }
            : {})}
        />
      </GlassContext.Provider>
    );
  }
  GlassComponent.displayName = `Glass(${Component.displayName ?? Component.name})`;
  return GlassComponent;
}

export function useGlassEnabled(glass?: boolean) {
  const context = useContext(GlassContext);
  return glass ?? (context.enabled && !context.surface);
}

export type GlassTextColor = [number, number, number, number];
export const maxGlassTextColors = 32;

export class GlassContrastError extends Error {
  override name = "GlassContrastError";
}

let colorContext: CanvasRenderingContext2D | null = null;

export function parseGlassColor(color: string): GlassTextColor {
  if (!color || color === "transparent") return [0, 0, 0, 0];
  if (!colorContext) {
    const canvas = document.createElement("canvas");
    canvas.width = canvas.height = 1;
    colorContext = canvas.getContext("2d", { willReadFrequently: true });
  }
  const context = colorContext;
  if (!context) return [0.5, 0.5, 0.5, 1];
  context.clearRect(0, 0, 1, 1);
  context.fillStyle = "#000";
  context.fillStyle = color;
  context.fillRect(0, 0, 1, 1);
  const bytes = context.getImageData(0, 0, 1, 1).data;
  return [bytes[0] / 255, bytes[1] / 255, bytes[2] / 255, bytes[3] / 255];
}

function luminance(color: readonly number[]) {
  const linear = color
    .slice(0, 3)
    .map((channel) =>
      channel <= 0.04045 ? channel / 12.92 : ((channel + 0.055) / 1.055) ** 2.4,
    );
  return linear[0] * 0.2126 + linear[1] * 0.7152 + linear[2] * 0.0722;
}

export function glassTextContrast(
  background: readonly number[],
  text: GlassTextColor,
) {
  const foreground = text
    .slice(0, 3)
    .map(
      (channel, index) => channel * text[3] + background[index] * (1 - text[3]),
    );
  const first = luminance(background) + 0.05;
  const second = luminance(foreground) + 0.05;
  return Math.max(first, second) / Math.min(first, second);
}

export function resolveGlassContrastTint(
  tint: [number, number, number],
  colors: readonly GlassTextColor[],
  minimum: number,
): [number, number, number] | undefined {
  const passes = (candidate: [number, number, number]) =>
    colors.every((color) => glassTextContrast(candidate, color) >= minimum);
  if (passes(tint)) return tint;
  let result: [number, number, number] | undefined;
  let distance = Number.POSITIVE_INFINITY;
  const consider = (candidate: [number, number, number]) => {
    const delta = candidate.reduce(
      (total, channel, index) => total + (channel - tint[index]) ** 2,
      0,
    );
    if (delta < distance && passes(candidate)) {
      result = candidate;
      distance = delta;
    }
  };
  for (let step = 0; step <= 255; step++) {
    const value = step / 255;
    consider([value, value, value]);
    for (const endpoint of [0, 1])
      consider(
        tint.map(
          (channel) =>
            Math.round((channel * (1 - value) + endpoint * value) * 255) / 255,
        ) as [number, number, number],
      );
  }
  return result;
}

export class GlassTextContrastCache {
  private revision = 0;
  private readonly entries = new WeakMap<
    HTMLElement,
    {
      revision: number;
      colors: GlassTextColor[];
      controls: {
        element: HTMLInputElement | HTMLTextAreaElement;
        filled: boolean;
        placeholder: string;
      }[];
    }
  >();

  invalidate() {
    this.revision++;
  }

  read(surface: HTMLElement): GlassTextColor[] {
    const cached = this.entries.get(surface);
    if (
      cached?.revision === this.revision &&
      cached.controls.every(
        ({ element, filled, placeholder }) =>
          Boolean(element.value) === filled &&
          element.placeholder === placeholder,
      )
    )
      return cached.colors;
    const colors = new Map<string, GlassTextColor>();
    const controls: {
      element: HTMLInputElement | HTMLTextAreaElement;
      filled: boolean;
      placeholder: string;
    }[] = [];
    const add = (color: string, opacity = 1) => {
      const parsed = parseGlassColor(color);
      parsed[3] *= opacity;
      if (parsed[3] <= 0) return;
      colors.set(parsed.join(","), parsed);
    };
    const visit = (element: Element, opacity: number) => {
      if (element !== surface && element.getAttribute("data-glass") === "true")
        return;
      const style = getComputedStyle(element);
      const alpha = Number.parseFloat(style.opacity);
      const effectiveOpacity = opacity * (Number.isFinite(alpha) ? alpha : 1);
      if (
        effectiveOpacity <= 0 ||
        style.display === "none" ||
        style.visibility === "hidden" ||
        style.visibility === "collapse" ||
        element.hasAttribute("hidden") ||
        element.getAttribute("aria-hidden") === "true" ||
        ["SCRIPT", "STYLE", "TEMPLATE", "SVG", "IFRAME"].includes(
          element.tagName.toUpperCase(),
        )
      )
        return;
      if (
        element !== surface &&
        ((style.backgroundImage && style.backgroundImage !== "none") ||
          parseGlassColor(style.backgroundColor)[3] > 0)
      )
        return;
      const input = element as HTMLInputElement | HTMLTextAreaElement;
      if (element.tagName === "INPUT" || element.tagName === "TEXTAREA") {
        if (element.tagName === "INPUT" && input.type === "hidden") return;
        controls.push({
          element: input,
          filled: Boolean(input.value),
          placeholder: input.placeholder,
        });
        if (input.value) add(style.color, effectiveOpacity);
        else if (input.placeholder) {
          const placeholder = getComputedStyle(element, "::placeholder");
          const placeholderOpacity = Number.parseFloat(placeholder.opacity);
          add(
            placeholder.color || style.color,
            effectiveOpacity *
              (Number.isFinite(placeholderOpacity) ? placeholderOpacity : 1),
          );
        }
        return;
      }
      if (
        [...element.childNodes].some(
          (node) => node.nodeType === 3 && Boolean(node.textContent?.trim()),
        )
      )
        add(style.color, effectiveOpacity);
      for (const child of element.children) visit(child, effectiveOpacity);
    };
    visit(surface, 1);
    if (!colors.size) add(getComputedStyle(surface).color);
    const result = [...colors.values()];
    this.entries.set(surface, {
      revision: this.revision,
      colors: result,
      controls,
    });
    return result;
  }
}

export const glassDefaults = {
  strength: 22,
  tintOpacity: 0.1,
  highlight: 0.3,
  minimumContrast: 0,
} as const;

export const glassMaterials = {
  clear: glassDefaults,
  regular: { ...glassDefaults, tintOpacity: 0.35 },
} as const;

export type GlassMaterial = keyof typeof glassMaterials;

export function glassRadii(
  width: number,
  height: number,
  radii: [string, string, string, string],
) {
  const corners = radii.map((value) => {
    const [horizontal = "0", vertical = horizontal] = value.split(/\s+/);
    const resolve = (length: string, size: number) =>
      Math.max(
        0,
        (Number.parseFloat(length) || 0) *
          (length.endsWith("%") ? size / 100 : 1),
      );
    return { x: resolve(horizontal, width), y: resolve(vertical, height) };
  });
  const [tl, tr, br, bl] = corners;
  const scale = Math.min(
    1,
    width / (tl.x + tr.x),
    width / (bl.x + br.x),
    height / (tl.y + bl.y),
    height / (tr.y + br.y),
  );
  return corners.map((radius) => ({
    x: radius.x * scale,
    y: radius.y * scale,
  }));
}

function brightness(color: readonly number[]) {
  return Math.min(
    1,
    Math.max(0, color[0] * 0.2126 + color[1] * 0.7152 + color[2] * 0.0722),
  );
}

function surfaceBrightness(
  foreground: readonly number[],
  background?: readonly number[],
) {
  return background ? brightness(background) : 1 - brightness(foreground);
}

export function glassEdge(
  width: number,
  height: number,
  radii: [string, string, string, string],
  highlight: number,
  color: readonly number[] = [1, 1, 1],
  background?: readonly number[],
) {
  if (highlight <= 0 || width <= 0 || height <= 0) return "none";
  const corners = glassRadii(width, height, radii);
  const outline = (requestedInset: number) => {
    const inset = Math.min(requestedInset, width / 2, height / 2);
    const [tl, tr, br, bl] = corners.map((radius) => ({
      x: Math.max(0, radius.x - inset),
      y: Math.max(0, radius.y - inset),
    }));
    const right = width - inset;
    const bottom = height - inset;
    return `M${inset + tl.x} ${inset}H${right - tr.x}A${tr.x} ${tr.y} 0 0 1 ${right} ${inset + tr.y}V${bottom - br.y}A${br.x} ${br.y} 0 0 1 ${right - br.x} ${bottom}H${inset + bl.x}A${bl.x} ${bl.y} 0 0 1 ${inset} ${bottom - bl.y}V${inset + tl.y}A${tl.x} ${tl.y} 0 0 1 ${inset + tl.x} ${inset}Z`;
  };
  const opacity =
    Math.min(1, highlight * 1.7) *
    (0.9 - surfaceBrightness(color, background) * 0.25);
  const bevel = Math.min(2.5, Math.min(width, height) * 0.045);
  const reflections = [
    { id: "top", azimuth: 270, opacity, stops: [0.95, 0.72, 0.5] },
    {
      id: "bottom",
      azimuth: 90,
      opacity: opacity * 0.85,
      stops: [0.5, 0.72, 0.95],
    },
  ];
  // A blurred silhouette supplies bevel normals. Lighting varies through its thickness,
  // rather than painting a constant-width bright stroke around the whole surface.
  // Saturated band coverage clips the feather without dimming subpixel bevels twice.
  const svg = `<svg xmlns="http://www.w3.org/2000/svg" width="${width}" height="${height}" viewBox="0 0 ${width} ${height}">
    <defs>
      <clipPath id="inside"><path d="${outline(0)}"/></clipPath>
      <filter id="soft" x="-5%" y="-5%" width="110%" height="110%">
        <feGaussianBlur stdDeviation="${bevel * 0.2}" result="soft"/>
        <feComponentTransfer in="SourceAlpha" result="band"><feFuncA type="linear" slope="2"/></feComponentTransfer>
        <feComposite in="soft" in2="band" operator="in"/>
      </filter>
      <mask id="bevel" maskUnits="userSpaceOnUse" x="0" y="0" width="${width}" height="${height}">
        <path d="${outline(bevel / 2)}" fill="none" stroke="white" stroke-width="${bevel}" filter="url(#soft)"/>
      </mask>
      ${reflections
        .map(
          ({ id, azimuth, stops }) => `
      <linearGradient id="${id}Fade">
        <stop stop-color="white" stop-opacity="${stops[0]}"/>
        <stop offset=".5" stop-color="white" stop-opacity="${stops[1]}"/>
        <stop offset="1" stop-color="white" stop-opacity="${stops[2]}"/>
      </linearGradient>
      <mask id="${id}Light" maskUnits="userSpaceOnUse" x="0" y="0" width="${width}" height="${height}">
        <rect width="${width}" height="${height}" fill="url(#${id}Fade)"/>
      </mask>
      <filter id="${id}Reflection" x="-5%" y="-5%" width="110%" height="110%" color-interpolation-filters="sRGB">
        <feGaussianBlur in="SourceAlpha" stdDeviation="${bevel * 0.46}" result="height"/>
        <feSpecularLighting in="height" surfaceScale="${bevel * 1.12}" specularConstant="1.6" specularExponent="26" lighting-color="white">
          <feDistantLight azimuth="${azimuth}" elevation="32"/>
        </feSpecularLighting>
        <feComposite in2="SourceAlpha" operator="in"/>
      </filter>`,
        )
        .join("")}
    </defs>
    <g clip-path="url(#inside)" mask="url(#bevel)">
      ${reflections
        .map(
          ({ id, opacity: strength }) => `
      <g mask="url(#${id}Light)" opacity="${strength}">
        <path d="${outline(0)}" fill="white" filter="url(#${id}Reflection)"/>
      </g>`,
        )
        .join("")}
    </g>
  </svg>`;
  return `url("data:image/svg+xml,${encodeURIComponent(svg)}")`;
}

export function glassShadow(
  highlight: number,
  color: readonly number[] = [1, 1, 1],
  background?: readonly number[],
) {
  if (highlight <= 0) return "0 0 #0000";
  const opacity = Number(
    Math.min(
      (highlight / 3) * (1 + surfaceBrightness(color, background) * 0.3),
      0.28,
    ).toFixed(3),
  );
  return `1px -1px 2px -0.5px rgb(0 0 0 / ${opacity}), -1px 1px 2px -0.5px rgb(0 0 0 / ${Number((opacity * 0.7).toFixed(3))})`;
}

type RGB = [number, number, number];
type RGBA = [number, number, number, number];

function matches(left: RGBA, right: RGBA) {
  if (left[3] === 0) return false;
  // Compare premultiplied bytes: low-alpha Canvas colors lose RGB precision.
  const scale = left[3] * 255;
  return left
    .slice(0, 3)
    .every(
      (value, index) =>
        Math.abs(
          Math.round(value * scale) - Math.round(right[index] * scale),
        ) <= 1,
    );
}

/** Keep semantic paint independent from the transparency of the glass tint. */
export function glassMaterial({
  paint,
  tint,
  opacity,
  primary,
  foreground,
  background,
  text,
  overrideTint,
  surfaceColors = [],
  destructive,
  customPaint = false,
}: {
  paint: RGBA;
  tint: RGBA;
  opacity: number;
  primary: RGBA;
  foreground: RGBA;
  background: RGBA;
  text: RGBA;
  overrideTint?: RGBA;
  surfaceColors?: RGBA[];
  destructive?: RGBA;
  customPaint?: boolean;
}) {
  const chromatic =
    Math.max(...paint.slice(0, 3)) - Math.min(...paint.slice(0, 3)) > 0.04;
  const surface = surfaceColors.find(
    (color) => color[3] > 0 && matches(paint, color),
  );
  const semantic =
    paint[3] > 0 &&
    (customPaint ||
      (primary[3] > 0 && matches(paint, primary)) ||
      (destructive && destructive[3] > 0 && matches(paint, destructive)) ||
      (!surface && (paint[3] < 1 || (chromatic && !matches(paint, tint)))) ||
      (foreground[3] > 0 &&
        background[3] > 0 &&
        matches(paint, foreground) &&
        matches(text, background)));
  if (!semantic) {
    const base = overrideTint ?? surface ?? (paint[3] > 0 ? paint : tint);
    return { tint: base.slice(0, 3) as RGB, opacity: opacity * base[3] };
  }
  const glassTint = overrideTint ?? tint;
  const neutral = opacity * glassTint[3] * (1 - paint[3]);
  const combined = paint[3] + neutral;
  return {
    tint: paint
      .slice(0, 3)
      .map(
        (channel, index) =>
          (channel * paint[3] + glassTint[index] * neutral) / combined,
      ) as RGB,
    opacity: combined,
  };
}

export const glassMaxBevelWidth = 17;
export const glassBevelFraction = 0.25;
export const glassMaxEdgeClarity = 0.8;
// Covers maximum GPU displacement (64 × .45 + .45), 2px blur and antialiasing.
export const glassSamplePadding = 40;

export function glassBevelWidth(width: number, height: number) {
  return Math.min(
    glassMaxBevelWidth,
    Math.min(width, height) * glassBevelFraction,
  );
}

export function glassRefractionStrength(
  strength: number,
  width: number,
  height: number,
) {
  const bevel = glassBevelWidth(width, height);
  // The smoothstep profile has a maximum slope of 1.5 / bevel. With
  // the normal map's 0.45 scale and this gain, the sampling slope stays
  // above 0.1 even at saturation, while the lens becomes more pronounced.
  return ((bevel * strength) / (bevel + strength)) * (4 / 3);
}

export function glassRefractionProfile(depth: number, bevel: number) {
  const t = Math.max(0, Math.min(1, depth / bevel));
  return 1 - t * t * (3 - 2 * t);
}

import type {} from "@/lib/sui/types/webgpu";

/// <reference types="@webgpu/types" />

import {
  type Effect,
  effect,
  type Gpu,
  frame as gpuFrame,
  init,
  sampler,
  type Texture,
  target,
  texture,
} from "vgpu";

import {
  GlassContrastError,
  type GlassTextColor,
  maxGlassTextColors,
  resolveGlassContrastTint,
} from "@/lib/glass/contrast";
import { glassDefaults } from "@/lib/glass/defaults";
import {
  glassBevelFraction,
  glassMaxBevelWidth,
  glassMaxEdgeClarity,
  glassRefractionStrength,
} from "@/lib/glass/refraction";

export type GlassFrame = {
  pixelRatio?: number;
  width: number;
  height: number;
  margin: number;
  origin?: [number, number];
  radius: [number, number, number, number];
  radiusY?: [number, number, number, number];
  strength: number;
  blur: number;
  tint: [number, number, number];
  tintOpacity: number;
  foreground: [number, number, number];
  textColors?: readonly GlassTextColor[];
  minimumContrast?: number;
};

const shader = `
struct Params {
  surface: vec4f,
  source: vec4f,
  radii: vec4f,
  verticalRadii: vec4f,
  material: vec2f,
  tint: vec3f,
  minimumContrast: f32,
  contrastMaterial: vec4f,
  textColors: array<vec4f, ${maxGlassTextColors}>,
};
@group(0) @binding(0) var<uniform> params: Params;
@group(0) @binding(1) var background: texture_2d<f32>;
@group(0) @binding(2) var linearSampler: sampler;
@group(0) @binding(3) var sharpBackground: texture_2d<f32>;

@vertex fn vertexMain(@builtin(vertex_index) index: u32) -> @builtin(position) vec4f {
  var positions = array<vec2f, 3>(vec2f(-1.0, -1.0), vec2f(3.0, -1.0), vec2f(-1.0, 3.0));
  return vec4f(positions[index], 0.0, 1.0);
}
fn luminance(rgb: vec3f) -> f32 {
  let linear = select(rgb / vec3f(12.92), pow((rgb + vec3f(0.055)) / vec3f(1.055), vec3f(2.4)), rgb > vec3f(0.04045));
  return dot(linear, vec3f(0.2126, 0.7152, 0.0722));
}
fn contrast(a: vec3f, b: vec3f) -> f32 {
  let x = luminance(a) + 0.05;
  let y = luminance(b) + 0.05;
  return max(x, y) / min(x, y);
}
fn supportsTextContrast(background: vec3f) -> bool {
  for (var index = 0u; index < u32(params.contrastMaterial.w); index++) {
    let text = params.textColors[index];
    let foreground = mix(background, text.xyz, text.w);
    if (contrast(background, foreground) < params.minimumContrast) { return false; }
  }
  return true;
}
fn ellipseDistance(x: f32, y: f32, rx: f32, ry: f32) -> f32 {
  let k0 = sqrt(x * x / (rx * rx) + y * y / (ry * ry));
  let k1 = sqrt(x * x / (rx * rx * rx * rx) + y * y / (ry * ry * ry * ry));
  if (k1 == 0.0) { return -min(rx, ry); }
  return k0 * (k0 - 1.0) / k1;
}
fn roundedDistance(p: vec2f) -> f32 {
  let width = params.surface.x;
  let height = params.surface.y;
  var distance = max(max(-p.x, p.x - width), max(-p.y, p.y - height));
  if (params.radii.x > 0.0 && params.verticalRadii.x > 0.0 && p.x < params.radii.x && p.y < params.verticalRadii.x) {
    distance = max(distance, ellipseDistance(p.x - params.radii.x, p.y - params.verticalRadii.x, params.radii.x, params.verticalRadii.x));
  }
  if (params.radii.y > 0.0 && params.verticalRadii.y > 0.0 && p.x > width - params.radii.y && p.y < params.verticalRadii.y) {
    distance = max(distance, ellipseDistance(p.x - (width - params.radii.y), p.y - params.verticalRadii.y, params.radii.y, params.verticalRadii.y));
  }
  if (params.radii.z > 0.0 && params.verticalRadii.z > 0.0 && p.x > width - params.radii.z && p.y > height - params.verticalRadii.z) {
    distance = max(distance, ellipseDistance(p.x - (width - params.radii.z), p.y - (height - params.verticalRadii.z), params.radii.z, params.verticalRadii.z));
  }
  if (params.radii.w > 0.0 && params.verticalRadii.w > 0.0 && p.x < params.radii.w && p.y > height - params.verticalRadii.w) {
    distance = max(distance, ellipseDistance(p.x - params.radii.w, p.y - (height - params.verticalRadii.w), params.radii.w, params.verticalRadii.w));
  }
  return distance;
}
fn sourceColor(p: vec2f, clarity: f32) -> vec3f {
  let uv = clamp((p + params.source.zw) / params.source.xy, vec2f(0.0), vec2f(1.0));
  let blurred = textureSampleLevel(background, linearSampler, uv, 0.0).rgb;
  let sharp = textureSampleLevel(sharpBackground, linearSampler, uv, 0.0).rgb;
  return mix(blurred, sharp, clarity);
}
fn bevelProfile(depth: f32, width: f32) -> f32 {
  return 1.0 - smoothstep(0.0, width, depth);
}
@fragment fn fragmentMain(@builtin(position) pixel: vec4f) -> @location(0) vec4f {
  let p = pixel.xy * params.surface.xy / params.surface.zw;
  let distance = roundedDistance(p);
  let antialias = max(fwidth(distance) * 0.5, 0.00001);
  let gradient = vec2f(
    roundedDistance(p + vec2f(0.4, 0.0)) - roundedDistance(p - vec2f(0.4, 0.0)),
    roundedDistance(p + vec2f(0.0, 0.4)) - roundedDistance(p - vec2f(0.0, 0.4))
  ) + vec2f(0.00001);
  let normal = gradient / max(length(gradient), 0.00001);
  let depth = max(-distance, 0.0);
  let bevelWidth = min(${glassMaxBevelWidth}.0, min(params.surface.x, params.surface.y) * ${glassBevelFraction});
  let bevel = bevelProfile(depth, bevelWidth);
  var offset = normal * bevel;
  let edges = min(p, params.surface.xy - p);
  var corner = select(1u, 0u, p.x < params.surface.x * 0.5);
  if (p.y >= params.surface.y * 0.5) { corner = 3u - corner; }
  if (params.radii[corner] == 0.0 && params.verticalRadii[corner] == 0.0 && all(params.radii <= vec4f(params.surface.x * 0.5)) && all(params.verticalRadii <= vec4f(params.surface.y * 0.5)) && all(edges >= vec2f(0.0)) && all(edges < vec2f(bevelWidth))) {
    let signs = select(vec2f(1.0), vec2f(-1.0), p < params.surface.xy * 0.5);
    offset = signs * vec2f(bevelProfile(edges.x, bevelWidth), bevelProfile(edges.y, bevelWidth));
  }
  let displaced = p - offset * params.material.y * 0.45;
  let split = offset * min(params.material.y * 0.014, 0.45);
  let clarity = bevel * min(params.material.y / bevelWidth, 1.0) * ${glassMaxEdgeClarity};
  let sampled = vec3f(sourceColor(displaced + split, clarity).r, sourceColor(displaced, clarity).g, sourceColor(displaced - split, clarity).b);
  let luminanceValue = dot(sampled, vec3f(0.2126, 0.7152, 0.0722));
  let saturated = mix(vec3f(luminanceValue), sampled, 1.12);
  var result = mix(saturated, params.tint, params.material.x);
  result = clamp(result, vec3f(0.0), vec3f(1.0));
  if (params.minimumContrast > 0.0 && !supportsTextContrast(result)) {
    let safeTint = params.contrastMaterial.xyz;
    var lower = 0.0;
    var upper = 1.0;
    for (var index = 0; index < 8; index++) {
      let amount = (lower + upper) * 0.5;
      if (supportsTextContrast(mix(result, safeTint, amount))) {
        upper = amount;
      } else {
        lower = amount;
      }
    }
    result = mix(result, safeTint, upper);
    if (!supportsTextContrast(result)) { result = safeTint; }
  }
  return vec4f(result, 1.0 - smoothstep(-antialias, antialias, distance));
}`;

const gaussianShader = `
struct BlurParams {
  size: vec2f,
  step: vec2f,
  sigma: f32,
  radius: f32,
  padding: vec2f,
};
@group(0) @binding(0) var<uniform> params: BlurParams;
@group(0) @binding(1) var background: texture_2d<f32>;
@group(0) @binding(2) var linearSampler: sampler;
@vertex fn vertexMain(@builtin(vertex_index) index: u32) -> @builtin(position) vec4f {
  var positions = array<vec2f, 3>(vec2f(-1.0, -1.0), vec2f(3.0, -1.0), vec2f(-1.0, 3.0));
  return vec4f(positions[index], 0.0, 1.0);
}
@fragment fn fragmentMain(@builtin(position) pixel: vec4f) -> @location(0) vec4f {
  let uv = pixel.xy / params.size;
  var result = textureSampleLevel(background, linearSampler, uv, 0.0);
  var weight = 1.0;
  for (var offset = 1.0; offset <= params.radius; offset += 2.0) {
    let first = exp(-0.5 * pow(offset / params.sigma, 2.0));
    let second = select(0.0, exp(-0.5 * pow((offset + 1.0) / params.sigma, 2.0)), offset + 1.0 <= params.radius);
    let pairWeight = first + second;
    let delta = params.step * (offset + second / pairWeight);
    result += (textureSampleLevel(background, linearSampler, uv + delta, 0.0) + textureSampleLevel(background, linearSampler, uv - delta, 0.0)) * pairWeight;
    weight += 2.0 * pairWeight;
  }
  return result / weight;
}`;

type Background = {
  texture: Texture;
  width: number;
  height: number;
  filtered: Map<number, Texture>;
};

export class GlassRenderer {
  private readonly refraction: Effect;
  private readonly gaussian: [Effect, Effect];
  private readonly linearSampler: ReturnType<typeof sampler>;
  private readonly resources = new Set<Texture>();
  private readonly backgrounds = new Map<HTMLCanvasElement, Background>();
  private readonly contrastTints = new Map<string, [number, number, number]>();
  private queue: Promise<void> = Promise.resolve();
  private disposed = false;
  private failure?: Error;
  private readonly abort = () => this.destroy();
  private readonly unsubscribeError: () => void;

  private constructor(
    private readonly gpu: Gpu,
    private readonly signal?: AbortSignal,
  ) {
    this.unsubscribeError = gpu.onError((error) => {
      this.failure = new Error(error.message);
    });
    this.linearSampler = sampler(gpu, {
      minFilter: "linear",
      magFilter: "linear",
      addressModeU: "clamp-to-edge",
      addressModeV: "clamp-to-edge",
    });
    this.refraction = effect(gpu, shader, { label: "Glass refraction" });
    this.gaussian = [
      effect(gpu, gaussianShader, { label: "Glass horizontal blur" }),
      effect(gpu, gaussianShader, { label: "Glass vertical blur" }),
    ];
    signal?.addEventListener("abort", this.abort, { once: true });
    void gpu.gpu.lost.then((info) => {
      if (!this.disposed)
        this.failure = new Error(info.message || "Glass GPU device lost");
    });
  }

  static async create(signal?: AbortSignal): Promise<GlassRenderer> {
    if (signal?.aborted)
      throw new DOMException("Glass initialization cancelled", "AbortError");
    if (typeof navigator === "undefined" || !navigator.gpu)
      throw new Error("WebGPU unavailable");
    const gpu = await init({ powerPreference: "low-power", label: "Glass" });
    if (signal?.aborted) {
      gpu.dispose();
      throw new DOMException("Glass initialization cancelled", "AbortError");
    }
    let renderer: GlassRenderer | undefined;
    try {
      renderer = new GlassRenderer(gpu, signal);
      await Promise.all([
        renderer.refraction.compile({ colors: ["rgba8unorm"] }),
        renderer.gaussian[0].compile({ colors: ["rgba8unorm"] }),
        renderer.gaussian[1].compile({ colors: ["rgba8unorm"] }),
      ]);
      renderer.assertActive();
      return renderer;
    } catch (error) {
      if (renderer) renderer.destroy();
      else gpu.dispose();
      throw error;
    }
  }

  private assertActive() {
    if (this.disposed) throw new Error("Glass renderer disposed");
    if (this.failure) throw this.failure;
  }

  private releaseTexture(image: Texture) {
    if (this.resources.delete(image)) image.destroy();
  }

  private releaseBackground(source: HTMLCanvasElement) {
    const background = this.backgrounds.get(source);
    if (!background) return;
    this.backgrounds.delete(source);
    this.releaseTexture(background.texture);
    for (const image of background.filtered.values())
      this.releaseTexture(image);
  }

  private background(source: HTMLCanvasElement): Texture {
    const cached = this.backgrounds.get(source);
    if (
      cached &&
      cached.width === source.width &&
      cached.height === source.height
    ) {
      this.backgrounds.delete(source);
      this.backgrounds.set(source, cached);
      return cached.texture;
    }
    this.releaseBackground(source);
    const image = texture(this.gpu, {
      kind: "2d",
      label: "Glass background",
      size: [source.width, source.height],
      format: "rgba8unorm",
      usage: ["texture_binding", "copy_dst", "render_attachment"],
    });
    this.resources.add(image);
    try {
      this.gpu.gpu.queue.copyExternalImageToTexture(
        { source, flipY: false },
        { texture: image.gpu, premultipliedAlpha: false },
        [source.width, source.height],
      );
      this.backgrounds.set(source, {
        texture: image,
        width: source.width,
        height: source.height,
        filtered: new Map(),
      });
      // Serial rendering only needs the current background and its blur targets.
      if (this.backgrounds.size > 1) {
        const oldest = this.backgrounds.keys().next().value;
        if (oldest) this.releaseBackground(oldest);
      }
      return image;
    } catch (error) {
      this.releaseTexture(image);
      throw error;
    }
  }

  private filteredBackground(
    source: HTMLCanvasElement,
    blur: number,
    temporary: Texture[],
  ): Texture {
    const image = this.background(source);
    if (blur <= 0) return image;
    const background = this.backgrounds.get(source);
    if (!background) throw new Error("Glass background unavailable");
    const cached = background.filtered.get(blur);
    if (cached) {
      background.filtered.delete(blur);
      background.filtered.set(blur, cached);
      return cached;
    }
    // Share the original upload and each blur level across surfaces. Above 2 CSS
    // pixels, half-resolution Gaussian targets bound memory and sampling cost.
    const scale = blur >= 2 ? 0.5 : 1;
    const width = Math.max(1, Math.round(source.width * scale));
    const height = Math.max(1, Math.round(source.height * scale));
    const makeTarget = (label: string) => {
      const output = target(this.gpu, {
        label,
        size: [width, height],
        format: "rgba8unorm",
        clearColor: [0, 0, 0, 0],
      });
      this.resources.add(output.color);
      return output;
    };
    const horizontal = makeTarget("Glass Gaussian intermediate");
    temporary.push(horizontal.color);
    const vertical = makeTarget("Glass blurred background");
    background.filtered.set(blur, vertical.color);
    if (background.filtered.size > 3) {
      const oldest = background.filtered.keys().next().value;
      if (oldest !== undefined) {
        const previous = background.filtered.get(oldest);
        if (previous) this.releaseTexture(previous);
        background.filtered.delete(oldest);
      }
    }
    const sigma = blur * scale;
    const radius = Math.ceil(sigma * 3);
    const stages = [
      { input: image, output: horizontal, step: [1 / width, 0] },
      { input: horizontal.color, output: vertical, step: [0, 1 / height] },
    ];
    for (const [index, stage] of stages.entries()) {
      this.gaussian[index].set({
        params: {
          size: [width, height],
          step: stage.step,
          sigma,
          radius,
          padding: [0, 0],
        },
        background: stage.input,
        linearSampler: this.linearSampler,
      });
    }
    gpuFrame(this.gpu, (frame) => {
      frame.pass(horizontal, this.gaussian[0]);
      frame.pass(vertical, this.gaussian[1]);
    });
    return vertical.color;
  }

  render(source: HTMLCanvasElement, frame: GlassFrame): Promise<Blob> {
    const operation = this.queue.then(() => this.renderFrame(source, frame));
    this.queue = operation.then(
      () => {},
      () => {},
    );
    return operation;
  }

  private async renderFrame(
    source: HTMLCanvasElement,
    frame: GlassFrame,
  ): Promise<Blob> {
    this.assertActive();
    const textColors: readonly GlassTextColor[] = frame.textColors ?? [
      [...frame.foreground, 1],
    ];
    if (
      textColors.length > maxGlassTextColors ||
      textColors.some(
        (color) =>
          color.length !== 4 ||
          color.some(
            (channel) =>
              !Number.isFinite(channel) || channel < 0 || channel > 1,
          ),
      )
    )
      throw new GlassContrastError("Unsupported glass text colors");
    const minimum = frame.minimumContrast ?? glassDefaults.minimumContrast;
    const contrastMinimum = minimum > 0 ? minimum + 0.05 : 0;
    const contrastKey = JSON.stringify([
      frame.tint,
      textColors,
      contrastMinimum,
    ]);
    let contrastTint = this.contrastTints.get(contrastKey);
    if (!contrastTint) {
      contrastTint = resolveGlassContrastTint(
        frame.tint,
        textColors,
        contrastMinimum,
      );
      if (!contrastTint)
        throw new GlassContrastError(
          "Glass text colors have no shared contrast background",
        );
      if (this.contrastTints.size >= 64) this.contrastTints.clear();
      this.contrastTints.set(contrastKey, contrastTint);
    }
    if (
      ![
        frame.width,
        frame.pixelRatio ?? 1,
        frame.height,
        frame.margin,
        frame.strength,
        frame.blur,
        frame.tintOpacity,
        minimum,
        ...(frame.origin ?? [frame.margin, frame.margin]),
        ...frame.radius,
        ...(frame.radiusY ?? frame.radius),
        ...frame.tint,
        ...frame.foreground,
      ].every(Number.isFinite) ||
      frame.blur < 0 ||
      frame.blur > 24 ||
      frame.width <= 0 ||
      (frame.pixelRatio ?? 1) <= 0 ||
      (frame.pixelRatio ?? 1) > 2 ||
      frame.height <= 0 ||
      source.width <= 0 ||
      source.height <= 0
    )
      throw new Error("Invalid glass frame dimensions or material");
    const scale = Math.min(Math.max(window.devicePixelRatio || 1, 1), 2);
    const width = Math.max(1, Math.round(frame.width * scale));
    const height = Math.max(1, Math.round(frame.height * scale));
    const bytesPerRow = Math.ceil((width * 4) / 256) * 256;
    if (
      Math.max(width, height, source.width, source.height) >
        this.gpu.gpu.limits.maxTextureDimension2D ||
      bytesPerRow * height > this.gpu.gpu.limits.maxBufferSize
    )
      throw new Error("Glass frame exceeds GPU limits");
    const temporary: Texture[] = [];
    let scopeOpen = true;
    this.gpu.gpu.pushErrorScope("validation");
    try {
      const pixelRatio = frame.pixelRatio ?? 1;
      const input = this.filteredBackground(
        source,
        frame.blur * pixelRatio,
        temporary,
      );
      const output = target(this.gpu, {
        label: "Glass frame",
        size: [width, height],
        format: "rgba8unorm",
        clearColor: [0, 0, 0, 0],
      });
      this.resources.add(output.color);
      temporary.push(output.color);
      const padding = () =>
        Array.from({ length: maxGlassTextColors }, () => [0, 0, 0, 0]);
      const colors = padding();
      textColors.forEach((color, index) => {
        colors[index] = [...color];
      });
      this.refraction.set({
        params: {
          surface: [frame.width, frame.height, width, height],
          source: [
            source.width / pixelRatio,
            source.height / pixelRatio,
            ...(frame.origin ?? [frame.margin, frame.margin]),
          ],
          radii: frame.radius,
          verticalRadii: frame.radiusY ?? frame.radius,
          material: [
            frame.tintOpacity,
            glassRefractionStrength(frame.strength, frame.width, frame.height),
          ],
          tint: frame.tint,
          minimumContrast: contrastMinimum,
          contrastMaterial: [...contrastTint, textColors.length],
          textColors: colors,
        },
        background: input,
        sharpBackground: this.background(source),
        linearSampler: this.linearSampler,
      });
      gpuFrame(this.gpu, (frame) => frame.pass(output, this.refraction));
      await this.gpu.settled();
      const validation = await this.gpu.gpu.popErrorScope();
      scopeOpen = false;
      if (validation) throw new Error(validation.message);
      this.assertActive();
      const bytes = await output.color.read({ mipLevel: 0, region: "all" });
      this.assertActive();
      const canvas = document.createElement("canvas");
      canvas.width = width;
      canvas.height = height;
      const context = canvas.getContext("2d");
      if (!context) throw new Error("Unable to export glass pixels");
      const image = context.createImageData(width, height);
      image.data.set(bytes);
      context.putImageData(image, 0, 0);
      const blob = await new Promise<Blob>((resolve, reject) =>
        canvas.toBlob((result) => {
          if (result) resolve(result);
          else reject(new Error("Unable to export glass frame"));
        }, "image/png"),
      );
      canvas.width = canvas.height = 1;
      this.assertActive();
      return blob;
    } catch (error) {
      this.releaseBackground(source);
      throw error;
    } finally {
      if (scopeOpen) await this.gpu.gpu.popErrorScope().catch(() => {});
      for (const image of temporary) this.releaseTexture(image);
    }
  }

  destroy() {
    if (this.disposed) return;
    this.disposed = true;
    this.signal?.removeEventListener("abort", this.abort);
    this.unsubscribeError();
    for (const resource of this.resources) resource.destroy();
    this.resources.clear();
    this.backgrounds.clear();
    this.contrastTints.clear();
    this.gpu.dispose();
  }
}

