  "data-pressed",
  "aria-checked",
  "data-checked",
  "data-unchecked",
  "aria-selected",
  "data-selected",
  "data-active",
  "data-highlighted",
  "aria-invalid",
  "data-invalid",
  "disabled",
  "aria-hidden",
